export default {".radial-progress":{"@layer daisyui.l1.l2.l3":{"position":"relative","display":"inline-grid","height":"var(--size)","width":"var(--size)","flex-shrink":0,"place-content":"center","border-radius":"calc(infinity * 1px)","background-color":"transparent","vertical-align":"middle","box-sizing":"content-box","--value":"0","--size":"5rem","--thickness":"calc(var(--size) / 10)","--radialprogress":"calc(var(--value) * 1%)","@media (prefers-reduced-motion: no-preference)":{"transition":"--radialprogress 0.3s linear"},"@media (forced-colors: active)":{"&:before, &:after":{"color":"CanvasText","forced-color-adjust":"none"}},"&:before":{"position":"absolute","inset":"0px","border-radius":"calc(infinity * 1px)","content":"\"\"","background":"radial-gradient(farthest-side, currentColor 98%, #0000) top/var(--thickness) var(--thickness) no-repeat, conic-gradient(currentColor var(--radialprogress), #0000 0)","webkit-mask":"radial-gradient( farthest-side, #0000 calc(100% - var(--thickness)), #000 calc(100% + 0.5px - var(--thickness)) )","mask":"radial-gradient( farthest-side, #0000 calc(100% - var(--thickness)), #000 calc(100% + 0.5px - var(--thickness)) )"},"&:after":{"position":"absolute","border-radius":"calc(infinity * 1px)","background-color":"currentcolor","@media (prefers-reduced-motion: no-preference)":{"transition":"transform 0.3s linear"},"content":"\"\"","inset":"calc(50% - var(--thickness) / 2)","transform":"rotate(calc(var(--value) * 3.6deg - 90deg)) translate(calc(var(--size) / 2 - 50%))"}}}};